import itertools,json
people=set('KLMNPQR')
A=['KNR','MNP','LMQ','LNR','MNR']
B=['KLN','NPR','PQR','KMP','LPQ']
ad=[{2,6},{1,4,7},{6,7},{3,5},{1,6}]
bd=[{4,7},{2},{3,7},{4,5},{3,5,8}]
aa=[x for x in itertools.product(*A) if len(set(x))==5]
bb=[x for x in itertools.product(*B) if len(set(x))==5]
count=0
hist={}
w={}
for a in aa:
 for b in bb:
  common=set(a)&set(b)
  if len(common)!=3 or len(common&set('KQR'))!=1: continue
  days={p:set() for p in people}
  for p,d in zip(a,ad): days[p].update(d)
  for p,d in zip(b,bd): days[p].update(d)
  n=sum(len(d)>=3 for d in days.values())
  count+=1
  hist[n]=hist.get(n,0)+1
  w.setdefault(n,{'A':''.join(a),'B':''.join(b)})
lo,hi=min(hist),max(hist)
print(json.dumps({'feasible_linkages':count,'bounds':[lo,hi],'low_witness':w[lo],'high_witness':w[hi],'decision':'confirmed' if lo>=3 else 'excluded' if hi<3 else 'undetermined'}))
print('histogram',hist)
for n in (lo,hi):
 a=w[n]['A'];b=w[n]['B'];d={p:set() for p in people}
 for p,ds in zip(a,ad):d[p]|=ds
 for p,ds in zip(b,bd):d[p]|=ds
 print(n, {p:sorted(d[p]) for p in sorted(people)})

